-- Structural fixtures based on the supplied psql schema. No production records or credentials.
CREATE TABLE restaurant_admin(id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,password text NOT NULL,restaurentname text NOT NULL,phonenumber text NOT NULL,branchname text NOT NULL,country text NOT NULL,branchaddress text NOT NULL,created_at timestamp DEFAULT CURRENT_TIMESTAMP,is_email_verified boolean DEFAULT false,is_phonenumber_verified boolean DEFAULT false,countrycode text,is_active boolean NOT NULL DEFAULT true,is_suspended boolean NOT NULL DEFAULT false,payment_settings jsonb DEFAULT '{}',display_settings jsonb DEFAULT '{}');
CREATE TABLE restaurant_area(id text PRIMARY KEY,area_name text NOT NULL,restaurant_id text NOT NULL REFERENCES restaurant_admin(id));
CREATE TABLE restaurant_tables(id text PRIMARY KEY,name text NOT NULL,seat_capacity integer NOT NULL,is_active text NOT NULL,restaurant_id text NOT NULL REFERENCES restaurant_admin(id),area_id text NOT NULL REFERENCES restaurant_area(id),status text DEFAULT 'free',last_used_at timestamp,assigned_waiter_id text,reservation_info jsonb);
CREATE TABLE restaurant_menu_category(id text PRIMARY KEY,menu_category_name text NOT NULL,restaurant_id text NOT NULL REFERENCES restaurant_admin(id));
CREATE TABLE restaurant_menu_items(id text PRIMARY KEY,item_name text NOT NULL,item_category text NOT NULL,item_dec text NOT NULL,preparation_time text NOT NULL,availability text NOT NULL,image_url text,price text NOT NULL,menu_category_id text NOT NULL REFERENCES restaurant_menu_category(id),restaurant_id text NOT NULL REFERENCES restaurant_admin(id),category_name text NOT NULL);
CREATE TABLE restaurant_staff(id text PRIMARY KEY,name text NOT NULL,email text NOT NULL,phone_number text NOT NULL,joined_at timestamp DEFAULT CURRENT_TIMESTAMP,role text NOT NULL,shift_timing text,salary text,experience integer DEFAULT 0,status text DEFAULT 'active',ratings integer DEFAULT 0,total_orders_served integer DEFAULT 0,address text,restaurant_id text REFERENCES restaurant_admin(id),assigned_tables text,staff_image text,password text NOT NULL,waiter_request text);
CREATE TABLE orders(id varchar(50) PRIMARY KEY,table_id text,restaurant_id text NOT NULL,customer_name varchar(100),items jsonb NOT NULL,total_price text NOT NULL,status varchar(20) NOT NULL DEFAULT 'pending',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),customer_id text,waiter_id text,order_status text NOT NULL,table_name text,note text,waiter_name text,tax_amount text,discount_amount text,order_number integer);
CREATE TABLE payments(id varchar(255) PRIMARY KEY,restaurant_id varchar(255) NOT NULL REFERENCES restaurant_admin(id) ON DELETE CASCADE,order_id varchar(255) REFERENCES orders(id) ON DELETE SET NULL,order_number integer,table_id varchar(255) REFERENCES restaurant_tables(id) ON DELETE SET NULL,table_name varchar(255),amount numeric(10,2) NOT NULL,payment_method varchar(50) NOT NULL CHECK(payment_method IN ('Cash','UPI','Card','Online')),payment_status varchar(50) DEFAULT 'Paid' CHECK(payment_status IN ('INITIATED','PENDING_CONFIRMATION','SUCCESS','FAILED','Paid','Pending','Failed')),transaction_id varchar(255),notes text,created_at timestamp DEFAULT CURRENT_TIMESTAMP,updated_at timestamp DEFAULT CURRENT_TIMESTAMP,upi_id varchar(255));
CREATE TABLE reservations(id varchar(255) PRIMARY KEY,restaurant_id varchar(255) NOT NULL REFERENCES restaurant_admin(id) ON DELETE CASCADE,customer_name varchar(255) NOT NULL,email varchar(255) NOT NULL,phone varchar(50) NOT NULL,date date NOT NULL,time time NOT NULL,guests integer NOT NULL,table_id varchar(255) NOT NULL REFERENCES restaurant_tables(id) ON DELETE SET NULL,notes text DEFAULT 'No special requests',status varchar(50) DEFAULT 'pending',created_at timestamp DEFAULT CURRENT_TIMESTAMP,updated_at timestamp DEFAULT CURRENT_TIMESTAMP,CONSTRAINT reservations_status_check CHECK(status IN ('pending','success','cancelled')));
CREATE TABLE waiter_requests(id varchar(255) PRIMARY KEY,restaurant_id varchar(255) NOT NULL REFERENCES restaurant_admin(id) ON DELETE CASCADE,table_id varchar(255) NOT NULL REFERENCES restaurant_tables(id) ON DELETE SET NULL,table_name varchar(255),customer_id varchar(255),customer_name varchar(255),request_type varchar(50) DEFAULT 'general' CHECK(request_type IN ('general','bill','order','assistance','other')),status varchar(50) DEFAULT 'pending' CHECK(status IN ('pending','assigned','completed','cancelled')),assigned_waiter_id varchar(255) REFERENCES restaurant_staff(id) ON DELETE SET NULL,notes text,created_at timestamp DEFAULT CURRENT_TIMESTAMP,updated_at timestamp DEFAULT CURRENT_TIMESTAMP,completed_at timestamp);
CREATE TABLE admin_calls(id varchar(255) PRIMARY KEY,restaurant_id varchar(255) NOT NULL REFERENCES restaurant_admin(id) ON DELETE CASCADE,waiter_id varchar(255) NOT NULL REFERENCES restaurant_staff(id) ON DELETE CASCADE,waiter_name varchar(255),admin_id varchar(255) NOT NULL REFERENCES restaurant_admin(id) ON DELETE CASCADE,admin_name varchar(255),status varchar(50) DEFAULT 'pending' CHECK(status IN ('pending','answered','missed','cancelled')),message text,created_at timestamp DEFAULT CURRENT_TIMESTAMP,answered_at timestamp);
CREATE TABLE customer_details(id text PRIMARY KEY,name text NOT NULL,password text NOT NULL,phone text NOT NULL,email text NOT NULL);
CREATE TABLE restaurant_chat_messages(id varchar(255) PRIMARY KEY,restaurant_id varchar(255) NOT NULL REFERENCES restaurant_admin(id) ON DELETE CASCADE,sender_id varchar(255) NOT NULL,sender_role varchar(50) NOT NULL CHECK(sender_role IN ('admin','waiter')),sender_name varchar(255),message text NOT NULL,created_at timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE super_admin(id varchar(255) PRIMARY KEY,email varchar(255) NOT NULL UNIQUE,password varchar(255) NOT NULL,name varchar(255) NOT NULL DEFAULT 'Super Admin',created_at timestamp DEFAULT CURRENT_TIMESTAMP,updated_at timestamp DEFAULT CURRENT_TIMESTAMP);
